import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"可导入样例：GitHub Actions 纵向面（P3-04）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/samples/declarative-vertical-sample.md","filePath":"zh/samples/declarative-vertical-sample.md"}'),i={name:"zh/samples/declarative-vertical-sample.md"};function c(l,e,r,s,n,p){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="可导入样例-github-actions-纵向面-p3-04" tabindex="-1">可导入样例：GitHub Actions 纵向面（P3-04） <a class="header-anchor" href="#可导入样例-github-actions-纵向面-p3-04" aria-label="Permalink to &quot;可导入样例：GitHub Actions 纵向面（P3-04）&quot;">​</a></h1><p><code>declarative-vertical-sample.json</code> 是一份<strong>配置包</strong>（与 设置 → 高级 → 导入/导出配置 同格式），演示声明式组件的一条纵向闭环：同一个 <code>github.actions.runs</code> 状态在 L0 tile、L2 面板行、L3 详情三面共用同源事实，并在 L3 详情聚合第二个源（<code>http.quota</code> 额度）演示跨源绑定与缺源显示。</p><h2 id="里面有什么" tabindex="-1">里面有什么 <a class="header-anchor" href="#里面有什么" aria-label="Permalink to &quot;里面有什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>说明</th></tr></thead><tbody><tr><td><code>w-sample-ci</code></td><td>GitHub Actions 运行卡：tile / row / detail 三面全部声明式，detail 聚合额度源</td></tr><tr><td><code>w-sample-quota</code></td><td><code>http.quota</code> 额度卡：指向 GitHub 公共 <code>rate_limit</code> 端点，无需凭据即可出数；detail 面为 HTML 载体面（受控子集，2026-10-17 裁定）</td></tr><tr><td><code>conn-sample-github</code></td><td>GitHub 连接：包内只有 credentialRef，导入后在连接里录入 PAT</td></tr><tr><td><code>conn-sample-quota</code></td><td>HTTP 连接：可替换成任意返回 JSON 的额度接口</td></tr><tr><td><code>open-quota-doc</code></td><td>包内动作（open.url）：HTML 面按钮 <code>data-action</code> 引用它，导入即可点</td></tr></tbody></table><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><ol><li><strong>先备份</strong>：导入会整体替换五份配置（含动作库）——先在 设置 → 高级 → 导出配置 存一份。</li><li>设置 → 高级 → 导入配置，选择本文件。</li><li>连接页给 <code>conn-sample-github</code> 录入 PAT；把 <code>w-sample-ci</code> 的 <code>repository</code> / <code>workflow</code> 改成你的仓库。</li><li>钉选后走三面：tile（L0）→ 面板行（L2）→ 详情（L3），同一状态三处一致。</li></ol><h2 id="验什么" tabindex="-1">验什么 <a class="header-anchor" href="#验什么" aria-label="Permalink to &quot;验什么&quot;">​</a></h2><ul><li>[ ] 不改 C#：只编辑 JSON 组件树，保存后对应面立即变化（保存链只重绘，不重新取数）。</li><li>[ ] 三面同源：L0 / L2 / L3 显示同一份 <code>w-sample-ci</code> 状态。</li><li>[ ] 两源独立：额度源刷新不带动 CI 源取数；detail 的 QUOTA 区随额度源独立更新。</li><li>[ ] 缺源显示：停用/删除 <code>w-sample-quota</code> 后，detail 的 QUOTA 区出现「⚠ 缺少数据源：quota」，不冒充空值、不显示健康旧值；恢复后自动回填。</li><li>[ ] 清空回退：删掉 <code>components</code> / <code>sources</code> 键保存，三面全部回传统渲染。</li><li>[ ] 断网 / 恢复：断网期间 tile 与详情显示陈旧时间，恢复后自愈。</li><li>[ ] HTML 面回退：删掉动作库里 <code>open-quota-doc</code> 重新导入，详情页按钮位变「⚠ 动作不可用」诊断占位，其余面照常。</li></ul><p>以上运行时条目需在 Windows 真机验收。CI 结构门由 <code>DeclarativeSampleTests</code> 常青保证：树/源校验通过、附加源闭环指向包内组件、全文无密钥语义词；HTML 载体面解析过词表校验、<code>data-action</code> 闭环指向包内动作。</p>',9)])])}const m=t(i,[["render",c]]);export{u as __pageData,m as default};
